#include <stdio.h>

#ifndef APP_VERSION
#define APP_VERSION "dev"
#endif
#ifndef BUILD_PROFILE
#define BUILD_PROFILE "debug"
#endif

int main(void)
{
    printf("version=%s\n", APP_VERSION);
    printf("profile=%s\n", BUILD_PROFILE);
    return 0;
}

